BEGIN EXECUTE IMMEDIATE 'CREATE TABLE INFRANEXUM_ORG_ORGANIZATION (ID VARCHAR2(36 CHAR) PRIMARY KEY, CODE VARCHAR2(32 CHAR) NOT NULL UNIQUE, DISPLAY_NAME VARCHAR2(160 CHAR) NOT NULL, LEGAL_NAME VARCHAR2(255 CHAR) NOT NULL, COUNTRY_CODE CHAR(2 CHAR) NOT NULL, DEFAULT_LANGUAGE VARCHAR2(35 CHAR) NOT NULL, TIMEZONE VARCHAR2(80 CHAR) NOT NULL, CURRENCY CHAR(3 CHAR) NOT NULL, PARENT_ORGANIZATION_ID VARCHAR2(36 CHAR), STATUS VARCHAR2(32 CHAR) NOT NULL, VERSION NUMBER(19) NOT NULL, CREATED_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL, UPDATED_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL, CONSTRAINT CK_INX_ORG_CODE CHECK (REGEXP_LIKE(CODE,''^[A-Z0-9][A-Z0-9-]{2,31}$'')), CONSTRAINT CK_INX_ORG_STATE CHECK (STATUS IN (''PROVISIONING'',''ACTIVE'',''SUSPENDED'',''ARCHIVING'',''ARCHIVED'',''DELETION_PENDING'',''DELETED'')), CONSTRAINT CK_INX_ORG_VERSION CHECK (VERSION>=0), CONSTRAINT CK_INX_ORG_PARENT CHECK (PARENT_ORGANIZATION_ID IS NULL OR PARENT_ORGANIZATION_ID<>ID), CONSTRAINT CK_INX_ORG_UUIDV7 CHECK (REGEXP_LIKE(ID,''^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'')), CONSTRAINT FK_INX_ORG_PARENT FOREIGN KEY(PARENT_ORGANIZATION_ID) REFERENCES INFRANEXUM_ORG_ORGANIZATION(ID))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/
BEGIN EXECUTE IMMEDIATE 'CREATE INDEX IX_INX_ORG_STATUS ON INFRANEXUM_ORG_ORGANIZATION(STATUS)'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/
BEGIN EXECUTE IMMEDIATE 'CREATE TABLE INFRANEXUM_ORG_SUBDIVISION (ID VARCHAR2(36 CHAR) PRIMARY KEY, ORGANIZATION_ID VARCHAR2(36 CHAR) NOT NULL, CODE VARCHAR2(32 CHAR) NOT NULL, DISPLAY_NAME VARCHAR2(160 CHAR) NOT NULL, DESCRIPTION_TEXT VARCHAR2(4000 CHAR), TYPE_NAME VARCHAR2(32 CHAR) NOT NULL, STATUS VARCHAR2(16 CHAR) NOT NULL, PARENT_SUBDIVISION_ID VARCHAR2(36 CHAR), VERSION NUMBER(19) NOT NULL, CREATED_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL, UPDATED_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL, DELETED_AT TIMESTAMP(6) WITH TIME ZONE, CONSTRAINT UQ_INX_SUB_ORG_CODE UNIQUE(ORGANIZATION_ID,CODE), CONSTRAINT UQ_INX_SUB_ORG_ID UNIQUE(ORGANIZATION_ID,ID), CONSTRAINT FK_INX_SUB_ORG FOREIGN KEY(ORGANIZATION_ID) REFERENCES INFRANEXUM_ORG_ORGANIZATION(ID), CONSTRAINT FK_INX_SUB_PARENT FOREIGN KEY(ORGANIZATION_ID,PARENT_SUBDIVISION_ID) REFERENCES INFRANEXUM_ORG_SUBDIVISION(ORGANIZATION_ID,ID), CONSTRAINT CK_INX_SUB_TYPE CHECK (TYPE_NAME IN (''DEPARTMENT'',''SITE'',''FUNCTION'',''PROJECT'',''COST_CENTER'')), CONSTRAINT CK_INX_SUB_STATE CHECK (STATUS IN (''DRAFT'',''ACTIVE'',''INACTIVE'',''ARCHIVED'',''DELETED'')), CONSTRAINT CK_INX_SUB_SELF CHECK (PARENT_SUBDIVISION_ID IS NULL OR PARENT_SUBDIVISION_ID<>ID), CONSTRAINT CK_INX_SUB_DELETED CHECK ((STATUS=''DELETED'' AND DELETED_AT IS NOT NULL) OR STATUS<>''DELETED''), CONSTRAINT CK_INX_SUB_UUIDV7 CHECK (REGEXP_LIKE(ID,''^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'')))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/
BEGIN EXECUTE IMMEDIATE 'CREATE TABLE INFRANEXUM_ORG_TEMP_SCOPE (ID VARCHAR2(36 CHAR) PRIMARY KEY, ORGANIZATION_ID VARCHAR2(36 CHAR) NOT NULL, SUBDIVISION_ID VARCHAR2(36 CHAR), SCOPE_TYPE VARCHAR2(24 CHAR) NOT NULL, VALID_FROM TIMESTAMP(6) WITH TIME ZONE NOT NULL, VALID_TO TIMESTAMP(6) WITH TIME ZONE, VERSION NUMBER(19) NOT NULL, CREATED_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL, CONSTRAINT FK_INX_SCOPE_ORG FOREIGN KEY(ORGANIZATION_ID) REFERENCES INFRANEXUM_ORG_ORGANIZATION(ID), CONSTRAINT FK_INX_SCOPE_SUB FOREIGN KEY(ORGANIZATION_ID,SUBDIVISION_ID) REFERENCES INFRANEXUM_ORG_SUBDIVISION(ORGANIZATION_ID,ID), CONSTRAINT CK_INX_SCOPE_TYPE CHECK (SCOPE_TYPE IN (''LEGAL'',''GEOGRAPHIC'',''OPERATIONAL'',''ADMINISTRATIVE'',''DATA'')), CONSTRAINT CK_INX_SCOPE_PERIOD CHECK (VALID_TO IS NULL OR VALID_TO>VALID_FROM), CONSTRAINT CK_INX_SCOPE_UUIDV7 CHECK (REGEXP_LIKE(ID,''^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'')))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/
BEGIN EXECUTE IMMEDIATE 'CREATE TABLE INFRANEXUM_ORG_COMMAND_DEDUP (IDEMPOTENCY_KEY VARCHAR2(128 CHAR) PRIMARY KEY, PAYLOAD_SHA256 CHAR(64 CHAR) NOT NULL, RESOURCE_TYPE VARCHAR2(32 CHAR) NOT NULL, RESOURCE_ID VARCHAR2(36 CHAR) NOT NULL, CREATED_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL, CONSTRAINT CK_INX_DEDUP_HASH CHECK (REGEXP_LIKE(PAYLOAD_SHA256,''^[0-9a-f]{64}$'')), CONSTRAINT CK_INX_DEDUP_TYPE CHECK (RESOURCE_TYPE IN (''organization'',''organization-transition'',''subdivision'',''scope'')))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE!=-955 THEN RAISE; END IF; END;/
